-- =============================================================================
-- Elidune Legacy Database Large Dataset
-- =============================================================================
-- Generated dataset with:
--   - 200 users
--   - 10000 books
--   - 500 authors
--   - 50 series
--   - Daily loans (5-40 per workday)
-- =============================================================================

-- Cleanup if tables exist
DROP TABLE IF EXISTS borrows_archives CASCADE;
DROP TABLE IF EXISTS borrows CASCADE;
DROP TABLE IF EXISTS borrows_settings CASCADE;
DROP TABLE IF EXISTS remote_specimens CASCADE;
DROP TABLE IF EXISTS specimens CASCADE;
DROP TABLE IF EXISTS remote_items CASCADE;
DROP TABLE IF EXISTS items CASCADE;
DROP TABLE IF EXISTS z3950servers CASCADE;
DROP TABLE IF EXISTS fees CASCADE;
DROP TABLE IF EXISTS users CASCADE;
DROP TABLE IF EXISTS account_types CASCADE;
DROP TABLE IF EXISTS authors CASCADE;
DROP TABLE IF EXISTS editions CASCADE;
DROP TABLE IF EXISTS collections CASCADE;
DROP TABLE IF EXISTS series CASCADE;
DROP TABLE IF EXISTS sources CASCADE;

-- =============================================================================
-- REFERENCE TABLES
-- =============================================================================

CREATE TABLE account_types (
    id SERIAL PRIMARY KEY,
    name VARCHAR,
    items_rights CHAR(1) DEFAULT 'n',
    users_rights CHAR(1) DEFAULT 'n',
    loans_rights CHAR(1) DEFAULT 'n',
    items_archive_rights CHAR(1) DEFAULT 'n',
    borrows_rights CHAR(1),
    settings_rights CHAR(1)
);


SELECT setval('account_types_id_seq', 10);

-- =============================================================================
-- USERS
-- =============================================================================

CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    login VARCHAR,
    password VARCHAR,
    firstname VARCHAR,
    lastname VARCHAR,
    email VARCHAR,
    addr_street VARCHAR,
    addr_zip_code INTEGER,
    addr_city VARCHAR,
    phone VARCHAR,
    sex_id SMALLINT,
    account_type_id SMALLINT,
    subscription_type_id SMALLINT,
    fee_id SMALLINT,
    last_payement_date TIMESTAMP DEFAULT NOW(),
    group_id INTEGER,
    barcode VARCHAR,
    notes VARCHAR,
    occupation VARCHAR,
    crea_date INTEGER,
    modif_date INTEGER,
    issue_date INTEGER,
    birthdate VARCHAR,
    archived_date INTEGER DEFAULT 0,
    public_type INTEGER
);


SELECT setval('users_id_seq', 211);

-- =============================================================================
-- AUTHORS
-- =============================================================================

CREATE TABLE authors (
    id SERIAL PRIMARY KEY,
    key VARCHAR UNIQUE,
    lastname VARCHAR,
    firstname VARCHAR,
    bio VARCHAR,
    notes VARCHAR
);


SELECT setval('authors_id_seq', 510);

-- =============================================================================
-- PUBLISHERS
-- =============================================================================

CREATE TABLE editions (
    id SERIAL PRIMARY KEY,
    key VARCHAR,
    name VARCHAR,
    place VARCHAR,
    notes VARCHAR
);


SELECT setval('editions_id_seq', 30);

-- =============================================================================
-- COLLECTIONS
-- =============================================================================

CREATE TABLE collections (
    id SERIAL PRIMARY KEY,
    key VARCHAR,
    title1 VARCHAR,
    title2 VARCHAR,
    title3 VARCHAR,
    issn VARCHAR
);


SELECT setval('collections_id_seq', 40);

-- =============================================================================
-- SERIES
-- =============================================================================

CREATE TABLE series (
    id SERIAL PRIMARY KEY,
    key VARCHAR,
    name VARCHAR
);


SELECT setval('series_id_seq', 60);

-- =============================================================================
-- SOURCES
-- =============================================================================

CREATE TABLE sources (
    id SERIAL PRIMARY KEY,
    key VARCHAR,
    name VARCHAR
);


SELECT setval('sources_id_seq', 10);

-- =============================================================================
-- ITEMS
-- =============================================================================

CREATE TABLE items (
    id SERIAL PRIMARY KEY,
    media_type VARCHAR,
    identification VARCHAR,
    price VARCHAR,
    barcode VARCHAR,
    dewey VARCHAR,
    publication_date VARCHAR,
    lang SMALLINT,
    lang_orig SMALLINT,
    title1 VARCHAR,
    title2 VARCHAR,
    title3 VARCHAR,
    title4 VARCHAR,
    author1_ids INTEGER[],
    author1_functions VARCHAR,
    author2_ids INTEGER[],
    author2_functions VARCHAR,
    author3_ids INTEGER[],
    author3_functions VARCHAR,
    serie_id INTEGER,
    serie_vol_number SMALLINT,
    collection_id INTEGER,
    collection_number_sub SMALLINT,
    collection_vol_number SMALLINT,
    source_id INTEGER,
    source_date VARCHAR,
    source_norme VARCHAR,
    genre SMALLINT,
    subject VARCHAR,
    public_type SMALLINT,
    edition_id INTEGER,
    edition_date VARCHAR,
    nb_pages VARCHAR,
    format VARCHAR,
    content VARCHAR,
    addon VARCHAR,
    abstract VARCHAR,
    notes VARCHAR,
    keywords VARCHAR,
    nb_specimens SMALLINT DEFAULT 0,
    state VARCHAR,
    is_archive SMALLINT DEFAULT 0,
    archived_timestamp INTEGER,
    is_valid SMALLINT DEFAULT 1,
    crea_date INTEGER,
    modif_date INTEGER
);





















SELECT setval('items_id_seq', 10010);

-- =============================================================================
-- SPECIMENS
-- =============================================================================

CREATE TABLE specimens (
    id SERIAL PRIMARY KEY,
    id_item INTEGER,
    source_id INTEGER,
    identification VARCHAR,
    cote VARCHAR,
    place SMALLINT,
    status SMALLINT DEFAULT 98,
    codestat SMALLINT,
    notes VARCHAR,
    price VARCHAR,
    modif_date INTEGER,
    is_archive INTEGER DEFAULT 0,
    archive_date INTEGER DEFAULT 0,
    crea_date INTEGER
);






























































SELECT setval('specimens_id_seq', 30292);

-- =============================================================================
-- LOANS
-- =============================================================================

CREATE TABLE borrows (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL,
    specimen_id INTEGER NOT NULL,
    item_id INTEGER,
    date INTEGER NOT NULL,
    renew_date INTEGER,
    nb_renews SMALLINT DEFAULT 0,
    issue_date INTEGER,
    notes VARCHAR,
    returned_date INTEGER
);









SELECT setval('borrows_id_seq', 3479);

-- =============================================================================
-- LOAN ARCHIVES
-- =============================================================================

CREATE TABLE borrows_archives (
    id SERIAL PRIMARY KEY,
    item_id INTEGER NOT NULL,
    specimen_id INTEGER,
    date INTEGER NOT NULL,
    nb_renews SMALLINT,
    issue_date INTEGER,
    returned_date INTEGER,
    notes VARCHAR,
    borrower_public_type INTEGER,
    occupation VARCHAR,
    addr_city VARCHAR,
    sex_id SMALLINT,
    account_type_id SMALLINT
);

SELECT setval('borrows_archives_id_seq', 10);

-- =============================================================================
-- LOAN SETTINGS
-- =============================================================================

CREATE TABLE borrows_settings (
    id SERIAL PRIMARY KEY,
    media_type VARCHAR,
    nb_max SMALLINT,
    nb_renews SMALLINT,
    duration SMALLINT,
    notes VARCHAR,
    account_type_id SMALLINT
);


SELECT setval('borrows_settings_id_seq', 10);

-- =============================================================================
-- Z39.50 SERVERS
-- =============================================================================

CREATE TABLE z3950servers (
    id SERIAL PRIMARY KEY,
    address VARCHAR,
    port INTEGER DEFAULT 2200,
    name VARCHAR,
    description VARCHAR,
    activated INTEGER DEFAULT 0,
    login VARCHAR,
    password VARCHAR,
    database VARCHAR,
    format VARCHAR,
    encoding VARCHAR DEFAULT 'utf-8'
);


SELECT setval('z3950servers_id_seq', 10);

-- =============================================================================
-- FEES
-- =============================================================================

CREATE TABLE fees (
    id SERIAL PRIMARY KEY,
    "desc" VARCHAR,
    amount INTEGER DEFAULT 0
);


SELECT setval('fees_id_seq', 10);

-- =============================================================================
-- REMOTE ITEMS
-- =============================================================================

CREATE TABLE remote_items (
    id SERIAL PRIMARY KEY,
    media_type VARCHAR,
    identification VARCHAR,
    price VARCHAR,
    barcode VARCHAR,
    dewey VARCHAR,
    publication_date VARCHAR,
    lang SMALLINT,
    lang_orig SMALLINT,
    title1 VARCHAR,
    title2 VARCHAR,
    title3 VARCHAR,
    title4 VARCHAR,
    author1_ids INTEGER[],
    author1_functions VARCHAR,
    author2_ids INTEGER[],
    author2_functions VARCHAR,
    author3_ids INTEGER[],
    author3_functions VARCHAR,
    serie_id INTEGER,
    serie_vol_number SMALLINT,
    collection_id INTEGER,
    collection_number_sub SMALLINT,
    collection_vol_number SMALLINT,
    source_id INTEGER,
    source_date VARCHAR,
    source_norme VARCHAR,
    genre SMALLINT,
    subject VARCHAR,
    public_type SMALLINT,
    edition_id INTEGER,
    edition_date VARCHAR,
    nb_pages VARCHAR,
    format VARCHAR,
    content VARCHAR,
    addon VARCHAR,
    abstract VARCHAR,
    notes VARCHAR,
    keywords VARCHAR,
    nb_specimens SMALLINT,
    state VARCHAR,
    is_archive SMALLINT DEFAULT 0,
    archived_timestamp INTEGER,
    is_valid SMALLINT DEFAULT 0,
    modif_date INTEGER,
    crea_date INTEGER
);

CREATE TABLE remote_specimens (
    id SERIAL PRIMARY KEY,
    id_item INTEGER,
    source_id INTEGER,
    identification VARCHAR,
    cote VARCHAR,
    media_type VARCHAR,
    place SMALLINT,
    status SMALLINT,
    codestat SMALLINT,
    notes VARCHAR,
    price VARCHAR,
    creation_date INTEGER,
    modif_date INTEGER
);

-- =============================================================================
-- INDEXES
-- =============================================================================

CREATE INDEX users_id_key ON users (id);
CREATE INDEX users_login_key ON users (login);
CREATE INDEX authors_id_key ON authors (id);
CREATE INDEX authors_lastname_key ON authors (lastname);
CREATE INDEX editions_id_key ON editions (id);
CREATE INDEX items_id_key ON items (id);
CREATE INDEX items_identification_key ON items (identification);
CREATE INDEX items_title1_key ON items (title1);
CREATE INDEX specimens_id_key ON specimens (id);
CREATE INDEX specimens_id_item_key ON specimens (id_item);
CREATE INDEX specimens_identification_key ON specimens (identification);
CREATE INDEX borrows_id_key ON borrows (id);
CREATE INDEX borrows_user_id_key ON borrows (user_id);
CREATE INDEX borrows_specimen_id_key ON borrows (specimen_id);

